const fs = require("fs");

const files = [
  "data/eras.js",
  "data/timeline.js",
  "data/quiz.js",
  "data/debates.js",
  "data/rules.js",
  "data/curriculum.js",
  "data/experience.js",
  "data/story-blocks.js",
  "state.js",
  "utils.js",
  "content-service.js",
  "dom.js",
  "progress.js",
  "screen-assets.js",
  "screen-controller.js",
  "lesson-experience.js",
  "script.js"
];

function toClassicScript(file, source) {
  const output = source
    .replace(/import\s*\{[\s\S]*?\}\s*from\s*['"][^'"]+['"];\s*/g, "")
    .replace(/import\s+\{[^}]+\}\s+from\s+['"][^'"]+['"];\s*/g, "");

  return output
    .replace(/\bexport\s+const\s+/g, "const ")
    .replace(/\bexport\s+function\s+/g, "function ");
}

const bundle = [
  "// Generated by build-bundle.js. Edit source modules, then run: node build-bundle.js",
  ...files.map((file) => `\n// ${file}\n${toClassicScript(file, fs.readFileSync(file, "utf8"))}`)
].join("\n");

fs.writeFileSync("bundle.js", bundle);
console.log("bundle.js atualizado");
